import json, os
p = os.path.expanduser('~/.claude.json')
with open(p) as f:
    d = json.load(f)
servers = d.get('mcpServers', {})
if not servers:
    print("NO top-level mcpServers")
else:
    # redact env values for display safety
    out = {}
    for name, cfg in servers.items():
        c = dict(cfg)
        if 'env' in c and isinstance(c['env'], dict):
            c['env'] = {k: '<redacted-preview>' for k in c['env']}
        if 'headers' in c and isinstance(c['headers'], dict):
            c['headers'] = {k: '<redacted-preview>' for k in c['headers']}
        out[name] = c
    print(json.dumps(out, indent=2))
EOF

